mapper.select:
select
mn.* from Sec_Project mn
left join Sec_Info sec on sec.Sec_Id=mn.Sec_Id left join Sec_Price_Resultsf spr on spr.Sec_Id=sec.Sec_Id where spr.Spr_Id=#{sprId}

select
    sec.Sec_Name as secName,
    sec.Sec_Code as secCode,
    sec.Sec_Type as secType,
    sec.Sec_Bidding_Type as secBiddingType,
    sec.Sec_Organize_Form as secOrganizeForm,
    sec.Sec_Start_Time as secStartTime,
    sec.Sec_Bidding_Cycle as secBiddingCycle,
    sec.Sec_Place as secPlace,
    sec.Sec_Trading_Place as secTradingPlace,
    c2.C_Name as secTendereeName,
    c2.C_Abbreviation as secTendereeAbbName,
    c3.C_Name as sprCompanyName,
    c3.C_Abbreviation as sprCompanyAbbName,
    se.Se_Result as seResult,
    mn.*
    from  Sec_Price_Resultsf mn
    left join  Sec_Info sec on sec.Sec_Id=mn.Sec_Id
    left join  SYS_Company c2 on sec.Sec_Tenderee=c2.C_Id
    left join  SYS_Company c3 on mn.Spr_Company=c3.C_Id
    left join  Sec_Entrust se on se.Sec_Id=mn.Sec_Id
    and se.id=(select id from Sec_Entrust where Sec_Id=sec.Sec_Id and State=7 order by State_Time desc limit 1)

    
        and mn.Te_Id = #{params.teId}
    
    
        and sec.Sec_Id=#{params.secId}
    
    
        and sec.Sec_Id in (
        Select sp.Sec_Id from Sec_Project sp
        left join Pre_Project sppj on sppj.P_ID = sp.P_Id
        where sppj.P_ID = #{params.pId}
        )
    
    
        and sec.Sec_Type=#{params.secType}
    
    
        and sec.Sec_Organize_Form=#{params.secOrganizeForm}
    
    
        and sec.Sec_Bidding_Type=#{params.secBiddingType}
    
    
        and mn.State=#{params.state}
    
    
        and INSTR(mn.Spr_Prerequisites,#{params.sprPrerequisites})
    
    
        and INSTR(sec.Sec_Name,#{params.secName})
    
    
        
            
                and likeCname(#{params.secTendereeName},c2.C_Id)=true
            
            
                and INSTR(c2.C_Name,#{params.secTendereeName})
            
        
    
    
        
            
                and likeCname(#{params.sprCompanyName},c3.C_Id)=true
            
            
                and INSTR(c3.C_Name,#{params.sprCompanyName})
            
        
    
    
        and INSTR(mn.Spr_Create_Uname,#{params.sprCreateUname})
    
    
        and INSTR(sec.Sec_Place,#{params.secPlace})
    
    
        and INSTR(sec.Sec_Trading_Place,#{params.secTradingPlace})
    
    
        and INSTR(se.Se_Result,#{params.seResult})
    
    
        and sec.Sec_Start_Time>=#{params.secStartTimeStart}
    
    
        and sec.Sec_Start_Time<=#{params.secStartTimeEnd}
    
    
        and sec.Sec_Bidding_Cycle>=#{params.secBiddingCycleStart}
    
    
        and sec.Sec_Bidding_Cycle<=#{params.secBiddingCycleEnd}
    
    
        and mn.Spr_Con_Money>=#{params.sprConMoneyStart}
    
    
        and mn.Spr_Con_Money<=#{params.sprConMoneyEnd}
    
    
        and mn.Spr_Price_Ceiling>=#{params.sprPriceCeilingStart}
    
    
        and mn.Spr_Price_Ceiling<=#{params.sprPriceCeilingEnd}
    
    
        and mn.Spr_Amt>=#{params.sprAmtStart}
    
    
        and mn.Spr_Amt<=#{params.sprAmtEnd}
    
    
        and mn.Spr_Create_Time>=#{params.sprCreateTimeStart}
    
    
        and mn.Spr_Create_Time<=#{params.sprCreateTimeEnd}
    
    
        and mn.Sec_Id in (
        Select sp.Sec_Id from Sec_Project sp
        left join Pre_Project sppj on sppj.P_ID = sp.P_Id
        left join SYS_Department dep on sppj.P_Competent_Department = dep.D_Id
        
            
                and INSTR(dep.D_Name,#{params.pCompetentDepartmentName})
            
            
                
                    
                        and likePname(#{params.pName},sppj.P_Id)=true
                    
                    
                        and INSTR(sppj.P_Name,#{params.pName})
                    
                
            
        
        )
    


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.Spr_Create_Time DESC
